package L1Cache.DCache

import chisel3._
import chisel3.util._
import config.config._
import L1Cache.{HasL1CacheParameters, RVGParameters, RVGParamsKey}
import top.parameters._
case object DCacheParamsKey extends Field [DCacheParameters]

case class DCacheParameters
(
  NSets: Int = dcache_NSets,
  NWays: Int = dcache_NWays,
  //BlockWords: Int = dcache_BlockWords,
  NMshrEntry: Int = dcache_MshrEntry,
  NMshrSubEntry: Int = dcache_MshrSubEntry,
  NWshrEntry: Int = dcache_wshr_entry,
)

trait HasDCacheParameter extends HasL1CacheParameters {
  implicit val p: Parameters

  val dcacheParams = p(DCacheParamsKey)

  override def NSets: Int = dcacheParams.NSets
  override def NWays: Int = dcacheParams.NWays
  //override def BlockWords: Int = BlockWords
  override def NMshrEntry: Int = dcacheParams.NMshrEntry
  override def NMshrSubEntry: Int = dcacheParams.NMshrSubEntry
  def NWshrEntry: Int = dcacheParams.NWshrEntry
  def NBanks = NLanes
  //                                       |   blockOffset  |
  //                                     bankOffset       wordOffset
  // |32      tag       22|21   setIdx   11|10 9|8 bankIdx 2|1 0|

  //TL params
  def TLAOp_Get: UInt = 4.U(3.W)
  def TLAOp_PutFull: UInt = 0.U(3.W)
  def TLAOp_PutPart: UInt = 1.U(3.W)
  def TLAOp_Flush: UInt = 5.U(3.W)
  def TLAParam_Flush : UInt = 0.U(3.W)
  def TLAParam_Inv : UInt = 1.U(3.W)
  def TLAOp_Arith: UInt = 2.U(3.W)
  def TLAOp_Logic: UInt = 3.U(3.W)

  def TLAParam_ArithMin : UInt = 0.U(3.W)
  def TLAParam_ArithMax : UInt = 1.U(3.W)
  def TLAParam_ArithMinu : UInt = 2.U(3.W)
  def TLAParam_ArithMaxu : UInt = 3.U(3.W)
  def TLAParam_ArithAdd : UInt = 4.U(3.W)
  def TLAParam_LogicXor : UInt = 0.U(3.W)
  def TLAParam_LogicOr : UInt = 1.U(3.W)
  def TLAParam_LogicAnd : UInt = 2.U(3.W)
  def TLAParam_LogicSwap : UInt = 3.U(3.W)
  def TLAParam_LRSC : UInt = 1.U(3.W)
}
abstract class DCacheBundle(implicit val p: Parameters) extends Bundle with HasDCacheParameter
abstract class DCacheModule(implicit val p: Parameters) extends Module with HasDCacheParameter

package L1Cache.DCache

import L1Cache._
import chisel3._
import chisel3.util._
import mmu.SV32.paLen
import top.parameters._

class WSHRreq extends Bundle{
  val blockAddr = UInt((paLen - dcache_BlockOffsetBits - dcache_WordOffsetBits).W)//UInt((dcache_SetIdxBits+dcache_TagBits).W)
}
class DCacheWSHR(Depth:Int) extends Module{
  val io = IO(new Bundle{
    //push
    val pushReq = Flipped(DecoupledIO(new WSHRreq))
    val conflict = Output(Bool())
    val pushedIdx = Output(UInt(log2Up(Depth).W))
    //for invOrFlu
    val empty = Output(Bool())
    //pop
    val popReq = Flipped(ValidIO(UInt(log2Up(Depth).W)))
  })
 // assert(!(io.pushReq.valid && io.popReq.valid),"WSHR cant pop and push in same cycle")

  val blockAddrEntries = RegInit(VecInit(Seq.fill(Depth)(0.U((paLen - dcache_BlockOffsetBits - dcache_WordOffsetBits).W))))
  val valid: Vec[Bool] = RegInit(VecInit(Seq.fill(Depth)(false.B)))
  io.empty := !valid.reduceTree(_|_)

  //following circuit are same to L1TagAccess.scala tagChecker
  val pushMatchMask = Wire(UInt(Depth.W))
  pushMatchMask := Reverse(Cat(blockAddrEntries.zip(valid).map{
    case(bA,valid) => (bA === io.pushReq.bits.blockAddr) && valid}))
  assert(PopCount(pushMatchMask) <= 1.U,"WSHR dont store same bA in 2 entries")
  io.conflict := pushMatchMask.orR

  //pushReq.ready := !full
  io.pushReq.ready := !valid.reduceTree(_ & _)

  val nextEntryIdx = valid.indexWhere((x: Bool) => x === false.B)
  val PopPushInSameCycle = io.pushReq.fire && io.popReq.fire
  io.pushedIdx := Mux(PopPushInSameCycle,io.popReq.bits,nextEntryIdx)
  when(io.pushReq.fire && io.popReq.fire){
    blockAddrEntries(io.popReq.bits) := io.pushReq.bits.blockAddr
    valid(io.popReq.bits) := true.B
  }.elsewhen(io.pushReq.fire){
    blockAddrEntries(nextEntryIdx) := io.pushReq.bits.blockAddr
    valid(nextEntryIdx) := true.B
  }.elsewhen(io.popReq.valid){
    valid(io.popReq.bits) := false.B
  }
}

